package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const (
	version   = "a75b67b"
	commit    = "a75b67b73b9edb91dfc9f302dd108fa9d3ea5b05"
	buildDate = "2026-04-17 19:59 UTC"
	buildBy   = "build.sh"
