| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|
`

const example = `
Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...
`

type stringSlice []string

func (s *stringSlice) String() string     { return strings.Join(*s, ",") }
func (s *stringSlice) Set(v string) error { *s = append(*s, v); return nil }

type options struct {
	config        string
	excludes      stringSlice
	formatter     string
	maxOpenFiles  int
	setExitStatus bool
	showVersion   bool
	args          []string
}

func printUsage(out *os.File, progName string) {
	fmt.Fprintln(out, banner)
	fmt.Fprintln(out, strings.TrimLeft(example, "\n"))
	fmt.Fprintf(out, "Usage of %s:\n", progName)
	fmt.Fprintf(out, "  -config string\n")
	fmt.Fprintf(out, "    \tpath to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)\n")
	fmt.Fprintf(out, "  -exclude value\n")
	fmt.Fprintf(out, "    \tlist of globs which specify files to be excluded (i.e. -exclude foo/...)\n")
	fmt.Fprintf(out, "  -formatter string\n")
	fmt.Fprintf(out, "    \tformatter to be used for the output (i.e. -formatter stylish)\n")
	fmt.Fprintf(out, "  -max_open_files int\n")
	fmt.Fprintf(out, "    \tmaximum number of open files at the same time\n")
	fmt.Fprintf(out, "  -set_exit_status\n")
	fmt.Fprintf(out, "    \tset exit status to 1 if any issues are found, overwrites errorCode and warningCode in config\n")
	fmt.Fprintf(out, "  -version\n")
	fmt.Fprintf(out, "    \tget revive version\n")
}

// parseFlags parses the CLI args the same way Go's flag package does (order-preserving).
// Returns options, positional args, and an error for unknown/malformed flags.
func parseFlags(progName string, args []string) (*options, error) {
	opt := &options{}
	i := 0
	for i < len(args) {
		a := args[i]
		if len(a) == 0 || a[0] != '-' || a == "-" {
			break
		}
		if a == "--" {
			i++
			break
		}
		name := a[1:]
		if len(name) > 0 && name[0] == '-' {
			name = name[1:]
		}
		// split on '='
		var value string
		hasValue := false
		if eq := strings.IndexByte(name, '='); eq >= 0 {
			value = name[eq+1:]
			name = name[:eq]
			hasValue = true
		}
		switch name {
		case "h", "help":
			printUsage(os.Stderr, progName)
			os.Exit(0)
		case "version":
			opt.showVersion = true
			i++
		case "set_exit_status":
			if hasValue {
				if value != "true" && value != "false" && value != "1" && value != "0" {
					return nil, fmt.Errorf("invalid boolean value %q for -set_exit_status: parse error", value)
				}
				opt.setExitStatus = value == "true" || value == "1"
			} else {
				opt.setExitStatus = true
			}
			i++
		case "config":
			if hasValue {
				opt.config = value
				i++
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: -config")
				}
				opt.config = args[i+1]
				i += 2
			}
		case "formatter":
			if hasValue {
				opt.formatter = value
				i++
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: -formatter")
				}
				opt.formatter = args[i+1]
				i += 2
			}
		case "exclude":
			if hasValue {
				opt.excludes.Set(value)
				i++
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: -exclude")
				}
				opt.excludes.Set(args[i+1])
				i += 2
			}
		case "max_open_files":
			if hasValue {
				var n int
				if _, err := fmt.Sscanf(value, "%d", &n); err != nil {
					return nil, fmt.Errorf("invalid value %q for flag -max_open_files: parse error", value)
				}
				opt.maxOpenFiles = n
				i++
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: -max_open_files")
				}
				var n int
				if _, err := fmt.Sscanf(args[i+1], "%d", &n); err != nil {
					return nil, fmt.Errorf("invalid value %q for flag -max_open_files: parse error", args[i+1])
				}
				opt.maxOpenFiles = n
				i += 2
			}
		default:
			return nil, fmt.Errorf("flag provided but not defined: -%s", name)
		}
	}
	opt.args = args[i:]
	return opt, nil
}

func printVersion() {
	fmt.Printf("Version:\t%s\n", version)
	fmt.Printf("Commit:\t\t%s\n", commit)
	fmt.Printf("Built\t\t%s by %s\n", buildDate, buildBy)
}

func main() {
	progName := os.Args[0]
	opts, err := parseFlags(progName, os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		printUsage(os.Stderr, progName)
		os.Exit(2)
	}

	if opts.showVersion {
		printVersion()
		return
	}

	// Run lint.
	exitCode := runLint(opts)
	os.Exit(exitCode)
}

func runLint(opts *options) int {
	// Resolve config.
	cfg, err := loadConfig(opts.config)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}

	// Determine formatter
	formatterName := opts.formatter
	if formatterName == "" {
		formatterName = "default"
	}
	formatter, err := getFormatter(formatterName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}

	// Resolve files
	files, err := resolveFiles(opts.args, opts.excludes)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n\n", err.Error())
		return 1
	}

	// Lint
	failures := []Failure{}
	for _, f := range files {
		fs, err := lintFile(f, cfg)
		if err != nil {
			continue
		}
		failures = append(failures, fs...)
	}

	// Apply default severity
	for i := range failures {
		if failures[i].Severity == "" {
			failures[i].Severity = "warning"
		}
	}

	output := formatter.Format(failures)
	if output != "" {
		fmt.Print(output)
	}

	if opts.setExitStatus && len(failures) > 0 {
		return 1
	}
	return 0
}

// resolveFiles expands patterns (like ./... or specific .go files) into a file list.
func resolveFiles(args []string, excludes []string) ([]string, error) {
	if len(args) == 0 {
		args = []string{"."}
	}
	var out []string
	for _, a := range args {
		if strings.HasSuffix(a, "/...") || a == "./..." || a == "..." {
			root := strings.TrimSuffix(a, "/...")
			root = strings.TrimSuffix(root, "...")
			if root == "" || root == "." {
				root = "."
			}
			err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if info.IsDir() {
					base := filepath.Base(path)
					if base == "vendor" || base == "testdata" || strings.HasPrefix(base, ".") && base != "." {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(path, ".go") {
					out = append(out, path)
				}
				return nil
			})
			if err != nil {
				return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: %s", err.Error())
			}
			continue
		}
		info, err := os.Stat(a)
		if err != nil {
			// Emulate go/build error when path doesn't exist
			return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: go/build: go list %s: fork/exec /root/go/pkg/mod/golang.org/toolchain@v0.0.1-go1.24.0.linux-amd64/bin/go: no such file or directory\n", a)
		}
		if info.IsDir() {
			entries, err := os.ReadDir(a)
			if err != nil {
				return nil, err
			}
			for _, e := range entries {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
					out = append(out, filepath.Join(a, e.Name()))
				}
			}
			continue
		}
		out = append(out, a)
	}
	// Apply excludes
	if len(excludes) > 0 {
		var filtered []string
		for _, f := range out {
			skip := false
			for _, ex := range excludes {
				m, _ := filepath.Match(ex, f)
				if m || ex == f {
					skip = true
					break
				}
				if strings.HasSuffix(ex, "/...") {
					prefix := strings.TrimSuffix(ex, "/...")
					if strings.HasPrefix(f, prefix) {
						skip = true
						break
					}
				}
			}
			if !skip {
				filtered = append(filtered, f)
			}
		}
		out = filtered
	}
	return out, nil
}

// silence unused imports
var _ = exec.Command
EOF
