package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// parseTOML parses a subset of TOML sufficient for revive's config format.
// Supported: top-level key = value pairs (strings, ints, floats, bools, arrays of scalars),
// [section] and [section.name] tables with key/value pairs.
// Returns a Config or an error similar to BurntSushi/toml messages.
func parseTOML(input string) (*Config, error) {
	cfg := &Config{
		Severity:   "",
		Confidence: 0,
		Rules:      map[string]*RuleConfig{},
	}
	// Track current section path (nil = top level)
	var currentSection []string
	lines := strings.Split(input, "\n")
	for ln, rawLine := range lines {
		line := strings.TrimSpace(stripComment(rawLine))
		if line == "" {
			continue
		}
		lineNum := ln + 1

		// Table header: [...] or [[...]]
		if line[0] == '[' {
			if !strings.HasSuffix(line, "]") {
				return nil, fmt.Errorf("line %d: invalid table header", lineNum)
			}
			body := strings.TrimSpace(line[1 : len(line)-1])
			// support [rule.foo-bar] -> path ["rule","foo-bar"]
			currentSection = splitTOMLKey(body)
			// Create a rule config if applicable
			if len(currentSection) == 2 && currentSection[0] == "rule" {
				name := currentSection[1]
				if _, ok := cfg.Rules[name]; !ok {
					cfg.Rules[name] = &RuleConfig{Name: name}
				}
			}
			continue
		}

		// key = value
		eq := strings.IndexByte(line, '=')
		if eq < 0 {
			return nil, fmt.Errorf("line %d: expected '.' or '=', but got '%c' instead", lineNum, line[0])
		}
		key := strings.TrimSpace(line[:eq])
		valueStr := strings.TrimSpace(line[eq+1:])
		value, err := parseTOMLValue(valueStr)
		if err != nil {
			return nil, fmt.Errorf("line %d: %s", lineNum, err.Error())
		}

		if len(currentSection) == 0 {
			// top-level
			switch key {
			case "severity":
				if s, ok := value.(string); ok {
					cfg.Severity = s
				}
			case "confidence":
				switch v := value.(type) {
				case float64:
					cfg.Confidence = v
				case int64:
					cfg.Confidence = float64(v)
				}
			}
		} else if len(currentSection) == 2 && currentSection[0] == "rule" {
			name := currentSection[1]
			rc := cfg.Rules[name]
			if rc == nil {
				rc = &RuleConfig{Name: name}
				cfg.Rules[name] = rc
			}
			switch key {
			case "severity":
				if s, ok := value.(string); ok {
					rc.Severity = s
				}
			case "arguments":
				if arr, ok := value.([]interface{}); ok {
					rc.Arguments = arr
				}
			case "Disabled", "disabled":
				if b, ok := value.(bool); ok {
					rc.Disabled = b
				}
			}
		}
	}
	return cfg, nil
}

func stripComment(s string) string {
	inString := false
	var quote byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inString {
			if c == '\\' && i+1 < len(s) {
				i++
				continue
			}
			if c == quote {
				inString = false
			}
			continue
		}
		if c == '"' || c == '\'' {
			inString = true
			quote = c
			continue
		}
		if c == '#' {
			return s[:i]
		}
	}
	return s
}

func splitTOMLKey(s string) []string {
	var parts []string
	cur := strings.Builder{}
	inString := false
	var quote byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inString {
			if c == quote {
				inString = false
				continue
			}
			cur.WriteByte(c)
			continue
		}
		if c == '"' || c == '\'' {
			inString = true
			quote = c
			continue
		}
		if c == '.' {
			parts = append(parts, strings.TrimSpace(cur.String()))
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	if cur.Len() > 0 {
		parts = append(parts, strings.TrimSpace(cur.String()))
	}
	return parts
}

func parseTOMLValue(s string) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, fmt.Errorf("empty value")
	}
	if s == "true" {
		return true, nil
	}
	if s == "false" {
		return false, nil
	}
	// string
	if s[0] == '"' {
		if len(s) < 2 || s[len(s)-1] != '"' {
			return nil, fmt.Errorf("unterminated string")
		}
		return unquoteTOMLString(s[1 : len(s)-1]), nil
	}
	if s[0] == '\'' {
		if len(s) < 2 || s[len(s)-1] != '\'' {
			return nil, fmt.Errorf("unterminated literal string")
		}
		return s[1 : len(s)-1], nil
	}
	// array
	if s[0] == '[' {
		if s[len(s)-1] != ']' {
			return nil, fmt.Errorf("unterminated array")
		}
		inner := s[1 : len(s)-1]
		parts := splitTOMLArray(inner)
		var out []interface{}
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			v, err := parseTOMLValue(p)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	}
	// number
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		// But could be float too if has dot
		if !strings.ContainsAny(s, ".eE") {
			return i, nil
		}
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return nil, fmt.Errorf("unknown value %q", s)
}

func unquoteTOMLString(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

func splitTOMLArray(s string) []string {
	var parts []string
	depth := 0
	inString := false
	var quote byte
	cur := strings.Builder{}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inString {
			if c == '\\' && i+1 < len(s) {
				cur.WriteByte(c)
				cur.WriteByte(s[i+1])
				i++
				continue
			}
			if c == quote {
				inString = false
			}
			cur.WriteByte(c)
			continue
		}
		switch c {
		case '"', '\'':
			inString = true
			quote = c
			cur.WriteByte(c)
		case '[':
			depth++
			cur.WriteByte(c)
		case ']':
			depth--
			cur.WriteByte(c)
		case ',':
			if depth == 0 {
				parts = append(parts, cur.String())
				cur.Reset()
			} else {
				cur.WriteByte(c)
			}
		default:
			if unicode.IsSpace(rune(c)) && cur.Len() == 0 {
				continue
			}
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		parts = append(parts, cur.String())
	}
	return parts
}
EOF
echo "ok"

