package main

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"strings"
)

// lintFile parses a Go source file and returns failures according to cfg rules.
func lintFile(path string, cfg *Config) ([]Failure, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, src, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	ctx := &lintCtx{
		file:   f,
		fset:   fset,
		src:    src,
		cfg:    cfg,
		path:   path,
	}

	var failures []Failure
	// Apply rules if enabled in cfg.
	apply := func(name string, fn func(*lintCtx) []Failure) {
		rc, ok := cfg.Rules[name]
		if !ok {
			return
		}
		if rc != nil && rc.Disabled {
			return
		}
		for _, fail := range fn(ctx) {
			fail.RuleName = name
			if rc != nil && rc.Severity != "" {
				fail.Severity = rc.Severity
			} else if cfg.Severity != "" {
				fail.Severity = cfg.Severity
			}
			failures = append(failures, fail)
		}
	}

	apply("package-comments", rulePackageComments)
	apply("var-naming", ruleVarNaming)
	apply("exported", ruleExported)
	apply("dot-imports", ruleDotImports)
	apply("blank-imports", ruleBlankImports)
	apply("if-return", ruleIfReturn)
	apply("superfluous-else", ruleSuperfluousElse)
	apply("increment-decrement", ruleIncrementDecrement)
	apply("error-return", ruleErrorReturn)
	apply("error-naming", ruleErrorNaming)
	apply("range", ruleRange)
	apply("receiver-naming", ruleReceiverNaming)
	apply("indent-error-flow", ruleIndentErrorFlow)
	apply("errorf", ruleErrorf)
	apply("empty-block", ruleEmptyBlock)
	apply("unused-parameter", ruleUnusedParameter)
	apply("unreachable-code", ruleUnreachableCode)
	apply("redefines-builtin-id", ruleRedefinesBuiltinID)
	apply("time-naming", ruleTimeNaming)
	apply("context-as-argument", ruleContextAsArgument)
	apply("context-keys-type", ruleContextKeysType)
	apply("var-declaration", ruleVarDeclaration)
	apply("unexported-return", ruleUnexportedReturn)
	apply("error-strings", ruleErrorStrings)

	return failures, nil
}

type lintCtx struct {
	file *ast.File
	fset *token.FileSet
	src  []byte
	cfg  *Config
	path string
}

// Position helpers
func (c *lintCtx) pos(p token.Pos) Position {
	pos := c.fset.Position(p)
	return Position{Filename: pos.Filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column}
}

func (c *lintCtx) rangeFor(start, end token.Pos) FailurePosition {
	return FailurePosition{Start: c.pos(start), End: c.pos(end)}
}

// computeEndOfName computes end position for an identifier-like range.
// The "end" is typically start.Column + len(name).
func computeEndOfName(start Position, name string) Position {
	end := start
	end.Column += len(name)
	end.Offset += len(name)
	return end
}

// -------- rules --------

func rulePackageComments(c *lintCtx) []Failure {
	if c.file.Doc != nil && strings.HasPrefix(strings.TrimSpace(c.file.Doc.Text()), "") && len(c.file.Doc.List) > 0 {
		return nil
	}
	// Report at line 1 col 1
	// End is col = 1 + len("package x")
