					vs, ok := spec.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, id := range vs.Names {
						if !id.IsExported() {
							continue
						}
						if (d.Doc == nil || len(d.Doc.List) == 0) && (vs.Doc == nil || len(vs.Doc.List) == 0) {
							start := c.pos(id.Pos())
							end := computeEndOfName(start, id.Name)
							out = append(out, Failure{
								Failure:    "exported " + kind + " " + id.Name + " should have comment or be unexported",
								Category:   "comments",
								Position:   FailurePosition{Start: start, End: end},
								Confidence: 1,
							})
						}
					}
				}
			} else if d.Tok == token.TYPE {
				for _, spec := range d.Specs {
					ts, ok := spec.(*ast.TypeSpec)
					if !ok {
						continue
					}
					if !ts.Name.IsExported() {
						continue
					}
