func isErrorConstructor(e ast.Expr) bool {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return false
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	xid, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	if xid.Name == "errors" && sel.Sel.Name == "New" {
		return true
	}
	if xid.Name == "fmt" && sel.Sel.Name == "Errorf" {
		return true
	}
	return false
}

