func ruleUnusedParameter(c *lintCtx) []Failure {
	var out []Failure
	for _, decl := range c.file.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		if fd.Type == nil || fd.Type.Params == nil {
