					end := computeEndOfName(start, id.Name)
					out = append(out, Failure{
						Failure:    "parameter '" + id.Name + "' seems to be unused, consider removing or renaming it as _",
						Category:   "bad practice",
						Position:   FailurePosition{Start: start, End: end},
						Confidence: 1,
