// lintFile parses a Go source file and returns failures according to cfg rules.
func lintFile(path string, cfg *Config) ([]Failure, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, src, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	ctx := &lintCtx{
		file:   f,
		fset:   fset,
		src:    src,
		cfg:    cfg,
		path:   path,
	}

	var failures []Failure
	// Apply rules if enabled in cfg.
	apply := func(name string, fn func(*lintCtx) []Failure) {
		rc, ok := cfg.Rules[name]
		if !ok {
			return
		}
		if rc != nil && rc.Disabled {
			return
		}
		for _, fail := range fn(ctx) {
			fail.RuleName = name
			if rc != nil && rc.Severity != "" {
				fail.Severity = rc.Severity
			} else if cfg.Severity != "" {
				fail.Severity = cfg.Severity
			}
			failures = append(failures, fail)
