type lintCtx struct {
	file *ast.File
	fset *token.FileSet
	src  []byte
	cfg  *Config
	path string
}

// Position helpers
func (c *lintCtx) pos(p token.Pos) Position {
	pos := c.fset.Position(p)
	return Position{Filename: pos.Filename, Offset: pos.Offset, Line: pos.Line, Column: pos.Column}
}

func (c *lintCtx) rangeFor(start, end token.Pos) FailurePosition {
	return FailurePosition{Start: c.pos(start), End: c.pos(end)}
}

// computeEndOfName computes end position for an identifier-like range.
// The "end" is typically start.Column + len(name).
func computeEndOfName(start Position, name string) Position {
	end := start
	end.Column += len(name)
	end.Offset += len(name)
	return end
}

// -------- rules --------

func rulePackageComments(c *lintCtx) []Failure {
	if c.file.Doc != nil && strings.HasPrefix(strings.TrimSpace(c.file.Doc.Text()), "") && len(c.file.Doc.List) > 0 {
		return nil
	}
	// Report at line 1 col 1
	// End is col = 1 + len("package x")
	pkgLine := ""
	if len(c.src) > 0 {
		if idx := indexByte(c.src, '\n'); idx >= 0 {
			pkgLine = string(c.src[:idx])
		} else {
			pkgLine = string(c.src)
		}
	}
	start := Position{Filename: c.path, Offset: 0, Line: 1, Column: 1}
	end := Position{Filename: c.path, Offset: len(pkgLine), Line: 1, Column: len(pkgLine) + 1}
	return []Failure{{
		Failure:    "should have a package comment",
		Category:   "comments",
		Position:   FailurePosition{Start: start, End: end},
		Confidence: 1,
	}}
}

func indexByte(b []byte, c byte) int {
	for i, x := range b {
		if x == c {
			return i
		}
	}
	return -1
}

// Common initialisms used by golint/revive var-naming rule.
var commonInitialisms = map[string]bool{
	"ACL": true, "API": true, "ASCII": true, "CPU": true, "CSS": true,
	"DNS": true, "EOF": true, "GUID": true, "HTML": true, "HTTP": true,
	"HTTPS": true, "ID": true, "IP": true, "JSON": true, "LHS": true,
	"QPS": true, "RAM": true, "RHS": true, "RPC": true, "SLA": true,
	"SMTP": true, "SQL": true, "SSH": true, "TCP": true, "TLS": true,
	"TTL": true, "UDP": true, "UI": true, "GID": true, "UID": true,
	"UUID": true, "URI": true, "URL": true, "UTF8": true, "VM": true,
	"XML": true, "XMPP": true, "XSRF": true, "XSS": true,
}

func lintName(name string) (should string) {
	if name == "_" {
		return name
	}
	if strings.ContainsAny(name, "_") {
		// handle all-caps like SOME_CONST -> stays all caps? golint converts
		if strings.ToUpper(name) == name {
			// replace trailing/extra underscores; produce CamelCase by splitting
			parts := strings.Split(name, "_")
			var sb strings.Builder
			for _, p := range parts {
				if p == "" {
					continue
				}
				sb.WriteString(strings.ToUpper(p[:1]))
				sb.WriteString(strings.ToLower(p[1:]))
			}
			should = sb.String()
		} else {
			// lowerCamel
			parts := strings.Split(name, "_")
			var sb strings.Builder
			for i, p := range parts {
				if p == "" {
					continue
				}
				if i == 0 {
					sb.WriteString(strings.ToLower(p[:1]))
					sb.WriteString(p[1:])
				} else {
					sb.WriteString(strings.ToUpper(p[:1]))
					sb.WriteString(p[1:])
				}
			}
			should = sb.String()
		}
	} else {
		should = name
	}
	// Apply common initialisms
	should = applyInitialisms(should)
	return should
}

func applyInitialisms(name string) string {
	// naive: find Word boundaries based on upper->lower transitions
	var words []string
	start := 0
	for i := 1; i <= len(name); i++ {
		if i == len(name) {
			words = append(words, name[start:i])
			break
		}
		c := name[i]
		// Upper to lower: new word boundary at this upper
		if isUpper(c) && !isUpper(name[i-1]) {
			words = append(words, name[start:i])
			start = i
		}
	}
	for i, w := range words {
		up := strings.ToUpper(w)
		if commonInitialisms[up] {
			if i > 0 || up == up { // always apply, but first word stays as-is if unexported
				// if word is first and not capital, keep lowercase
				if i == 0 && !isUpper(w[0]) {
					words[i] = strings.ToLower(up)
				} else {
					words[i] = up
				}
			}
		}
	}
	return strings.Join(words, "")
}

func isUpper(b byte) bool { return b >= 'A' && b <= 'Z' }

func ruleVarNaming(c *lintCtx) []Failure {
	var out []Failure
	// Check package name
	if c.file.Name != nil {
		name := c.file.Name.Name
		bad := map[string]bool{"common": true, "util": true, "pkg": true, "utils": true, "helpers": true, "lib": true, "libraries": true, "types": true, "shared": true, "common": true, "misc": true}
		if bad[name] {
			start := c.pos(c.file.Name.Pos())
			end := computeEndOfName(start, name)
			out = append(out, Failure{
				Failure:    "should not have a root level package called " + name,
				Category:   "naming",
				Position:   FailurePosition{Start: start, End: end},
				Confidence: 1,
			})
		}
	}

	// Walk AST
	ast.Inspect(c.file, func(n ast.Node) bool {
		switch d := n.(type) {
		case *ast.FuncDecl:
			// Check parameters
			if d.Type != nil && d.Type.Params != nil {
				for _, field := range d.Type.Params.List {
					for _, id := range field.Names {
						checkVarName(c, &out, "func parameter", id)
					}
				}
			}
		case *ast.GenDecl:
			if d.Tok == token.VAR {
				for _, spec := range d.Specs {
					vs, ok := spec.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, id := range vs.Names {
						checkVarName(c, &out, "var", id)
					}
				}
			} else if d.Tok == token.CONST {
				for _, spec := range d.Specs {
					vs, ok := spec.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, id := range vs.Names {
						checkVarName(c, &out, "const", id)
					}
				}
			}
		}
		return true
	})
	return out
}

func checkVarName(c *lintCtx, out *[]Failure, what string, id *ast.Ident) {
	name := id.Name
	if name == "_" {
		return
	}
	// Check underscores
	if strings.Contains(name, "_") && !(what == "const" && strings.ToUpper(name) == name) {
		should := lintName(name)
		if should != name {
			start := c.pos(id.Pos())
			end := computeEndOfName(start, name)
			*out = append(*out, Failure{
				Failure:    "don't use underscores in Go names; " + what + " " + name + " should be " + should,
				Category:   "naming",
				Position:   FailurePosition{Start: start, End: end},
				Confidence: 0.8,
			})
			return
		}
	}
	// Check initialisms
	should := applyInitialisms(name)
	if should != name {
		start := c.pos(id.Pos())
		end := computeEndOfName(start, name)
		*out = append(*out, Failure{
			Failure:    what + " " + name + " should be " + should,
			Category:   "naming",
			Position:   FailurePosition{Start: start, End: end},
			Confidence: 0.8,
		})
	}
}

func ruleExported(c *lintCtx) []Failure {
	// Requires the file to have a package-level doc comment to apply? Actually
	// golint always applies it. But package-comments fires separately.
	var out []Failure
	// In main package, skip
	if c.file.Name != nil && c.file.Name.Name == "main" {
		return nil
	}
	for _, decl := range c.file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Recv != nil {
				continue // method - check with receiver type
			}
			if !d.Name.IsExported() {
