			if d.Doc == nil || len(d.Doc.List) == 0 {
				start := c.pos(d.Pos())
				end := computeEndOfName(start, "func "+d.Name.Name)
				out = append(out, Failure{
					Failure:    "exported function " + d.Name.Name + " should have comment or be unexported",
					Category:   "comments",
					Position:   FailurePosition{Start: start, End: end},
					Confidence: 1,
				})
			}
		case *ast.GenDecl:
			if d.Tok == token.VAR || d.Tok == token.CONST {
				kind := "var"
				if d.Tok == token.CONST {
					kind = "const"
				}
				for _, spec := range d.Specs {
					vs, ok := spec.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, id := range vs.Names {
						if !id.IsExported() {
							continue
						}
						if (d.Doc == nil || len(d.Doc.List) == 0) && (vs.Doc == nil || len(vs.Doc.List) == 0) {
