								Category:   "comments",
								Position:   FailurePosition{Start: start, End: end},
								Confidence: 1,
							})
						}
					}
				}
			} else if d.Tok == token.TYPE {
				for _, spec := range d.Specs {
					ts, ok := spec.(*ast.TypeSpec)
					if !ok {
						continue
					}
					if !ts.Name.IsExported() {
						continue
					}
					if (d.Doc == nil || len(d.Doc.List) == 0) && (ts.Doc == nil || len(ts.Doc.List) == 0) {
						start := c.pos(ts.Name.Pos())
						end := computeEndOfName(start, ts.Name.Name)
						out = append(out, Failure{
							Failure:    "exported type " + ts.Name.Name + " should have comment or be unexported",
							Category:   "comments",
							Position:   FailurePosition{Start: start, End: end},
							Confidence: 1,
						})
					}
				}
			}
		}
	}
	return out
}

