package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

// Formatter is an output formatter.
type Formatter interface {
	Format([]Failure) string
}

func getFormatter(name string) (Formatter, error) {
	switch name {
	case "default":
		return &defaultFormatter{}, nil
	case "json":
		return &jsonFormatter{}, nil
	case "ndjson":
		return &ndjsonFormatter{}, nil
	case "friendly":
		return &friendlyFormatter{}, nil
	case "stylish":
		return &stylishFormatter{}, nil
	case "checkstyle":
		return &checkstyleFormatter{}, nil
	case "sarif":
		return &sarifFormatter{}, nil
	case "plain":
		return &plainFormatter{}, nil
	case "unix":
		return &unixFormatter{}, nil
	default:
		return nil, fmt.Errorf("formatting - getting formatter: unknown formatter %s", name)
	}
}

type defaultFormatter struct{}

func (defaultFormatter) Format(fs []Failure) string {
	var b strings.Builder
	for _, f := range fs {
		fmt.Fprintf(&b, "%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure)
	}
	return b.String()
}

type jsonFormatter struct{}

func (jsonFormatter) Format(fs []Failure) string {
	if fs == nil {
		return "null"
	}
	data, _ := json.Marshal(fs)
	return string(data)
}

type ndjsonFormatter struct{}

func (ndjsonFormatter) Format(fs []Failure) string {
	var b strings.Builder
	for _, f := range fs {
		data, _ := json.Marshal(f)
		b.Write(data)
		b.WriteByte('\n')
	}
	return b.String()
