type friendlyFormatter struct{}

func (friendlyFormatter) Format(fs []Failure) string {
	var b strings.Builder
	errs, warns := 0, 0
	byRule := map[string][2]int{} // [errors, warnings]
	for _, f := range fs {
		icon := "⚠"
		if f.Severity == "error" {
			icon = "✘"
			errs++
		} else {
			warns++
		}
		fmt.Fprintf(&b, "  %s  https://revive.run/r#%s  %s\n", icon, f.RuleName, f.Failure)
		fmt.Fprintf(&b, "  %s:%d:%d\n\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column)
		v := byRule[f.RuleName]
		if f.Severity == "error" {
			v[0]++
		} else {
			v[1]++
		}
		byRule[f.RuleName] = v
	}
	if len(fs) == 0 {
		return ""
	}
	total := errs + warns
	icon := "⚠"
	if errs > 0 {
		icon = "✘"
	}
	fmt.Fprintf(&b, "%s %d %s (%d %s, %d %s)\n\n", icon, total, pluralize("problem", total), errs, pluralize("error", errs), warns, pluralize("warning", warns))
	// summary
	if errs > 0 {
		b.WriteString("Errors:\n")
		// gather error rules
		type item struct{ name string; count int }
		var items []item
		for name, v := range byRule {
			if v[0] > 0 {
				items = append(items, item{name, v[0]})
			}
		}
		sort.Slice(items, func(i, j int) bool {
			if items[i].count != items[j].count {
				return items[i].count > items[j].count
			}
			return items[i].name < items[j].name
		})
		for _, it := range items {
			fmt.Fprintf(&b, "  %d  %s\n", it.count, it.name)
		}
		b.WriteString("\n")
	}
	if warns > 0 {
		b.WriteString("Warnings:\n")
		type item struct{ name string; count int }
		var items []item
		for name, v := range byRule {
			if v[1] > 0 {
				items = append(items, item{name, v[1]})
			}
		}
		sort.Slice(items, func(i, j int) bool {
			if items[i].count != items[j].count {
				return items[i].count > items[j].count
			}
			return items[i].name < items[j].name
		})
		for _, it := range items {
			fmt.Fprintf(&b, "  %d  %s\n", it.count, it.name)
		}
		b.WriteString("\n\n")
	}
	return b.String()
}

func pluralize(word string, n int) string {
	if n == 1 {
		return word
	}
	return word + "s"
}

